func TestContextExistenceCheckShowsTheFixedDotInTheFooterLine(t *testing.T) {
	isolateHome(t)
	m := New()
	m.width, m.height = 100, 30
	m = feed(t, m, testutil.Key("enter")) // font check -> context name
	m.contextNameInput.SetValue("staging")
